changeSet.sql:
update exercise
set options_json = json_remove(options_json, '$.preferDecisionTreeBasedSupplementaryEnabled')
where json_contains_path(options_json, 'one', '$.preferDecisionTreeBasedSupplementaryEnabled');

changeSet.rollback:
update exercise
set options_json = json_set(options_json, '$.preferDecisionTreeBasedSupplementaryEnabled', false)
where not json_contains_path(options_json, 'one', '$.preferDecisionTreeBasedSupplementaryEnabled');
